Contract CoCoMEOrderProducts::placeOrder(): Boolean {

            precondition:
          self.CurrentOrderProduct <> null

            postcondition:
          self.CurrentOrderProduct.OrderStatus = OrderStatus::REQUESTED and result = true and if self.CurrentOrderProduct.ContainedEntries@pre->isEmpty() then self.CurrentOrderProduct.Amount = self.CurrentOrderProduct.Amount@pre else self.CurrentOrderProduct.Amount = self.CurrentOrderProduct.Amount@pre + self.CurrentOrderProduct.ContainedEntries@pre->sumBy(e:OrderEntry|e.SubAmount@pre) endif

        }
